mapper.select:
SELECT *
FROM visual_screen.vs_page_info_where a
WHERE 1 = 1 and a.sub_id = #{params.sub_id}

SELECT DISTINCT a.DACCT AS "DACCT",  AS "INDEX_VALUE"
FROM visual_screen.vs_three_budget_revenue a
WHERE 1 = 1 and INDEX_NAME = #{params.INDEX_NAME}
${params.whereInfo}
and PERIOD_FLAG = #{params.PERIOD_FLAG}
group by a.DACCT
order BY a.DACCT

SELECT DISTINCT a.DACCT AS "DACCT",  AS "INDEX_VALUE"
FROM visual_screen.vs_tax_revenue a
WHERE 1 = 1 and a.INDEX_NAME = #{params.INDEX_NAME}
${params.whereInfo}
and PERIOD_FLAG = #{params.PERIOD_FLAG}
GROUP BY a.DACCT
order BY a.DACCT

SELECT DISTINCT a.DACCT AS "DACCT",  AS "INDEX_VALUE"
FROM visual_screen.vs_income_expenditure a
