group by a.dacct
order BY a.DACCT

SELECT DISTINCT a.AREA_DSCR AS "name",  AS "value"
FROM visual_screen.vs_municipalities_directly a
WHERE 1 = 1 and INDEX_NAME = #{params.INDEX_NAME}
${params.whereInfo}
and PERIOD_FLAG = #{params.PERIOD_FLAG}
group by a.AREA_DSCR
order BY  desc

