SELECT DISTINCT a.DACCT AS "DACCT",  AS "INDEX_VALUE"
FROM visual_screen.vs_customs_revenue a
LEFT JOIN visual_screen.vs_customs_revenue a1
ON a1.DACCT = 
AND a.AREA_CODE = a1.AREA_CODE and a1.INDEX_NAME = #{params.INDEX_NAME}
WHERE 1 = 1 and a.INDEX_NAME = #{params.INDEX_NAME}
${params.whereInfo}
and a.PERIOD_FLAG = #{params.PERIOD_FLAG}
group BY a.DACCT
order BY a.DACCT

