SELECT a.DACCT AS "DACCT", ROUND(COALESCE(SUM(COALESCE(a.INDEX_VALUE, 0)), 0), 2) AS "INDEX_VALUE"
FROM visual_screen.vs_treasury_index a
WHERE 1 = 1 and INDEX_NAME = #{params.INDEX_NAME}
${params.whereInfo}
and PERIOD_FLAG = #{params.PERIOD_FLAG}
GROUP BY a.DACCT
ORDER BY a.DACCT

SELECT a.DACCT AS "DACCT", AS "INDEX_VALUE", AS "GROWTH_INDEX_VALUE" FROM visual_screen.vs_inventory_analyze a WHERE 1 = 1 ${params.whereInfo}
and a.PERIOD_FLAG IN ( #{params.PERIOD_FLAG}, CONCAT('b''', #{params.PERIOD_FLAG}, '''') )
group by a.DACCT ORDER BY a.DACCT

SELECT a.DACCT AS "DACCT", AS "INDEX_VALUE" FROM visual_screen.vs_inventory_form a WHERE 1 = 1 and INDEX_NAME = '${params.INDEX_NAME}' ${params.whereInfo}
and a.PERIOD_FLAG IN ( #{params.PERIOD_FLAG}, CONCAT('b''', #{params.PERIOD_FLAG}, '''') )
group by a.DACCT ORDER BY a.DACCT

